queries.query:
from(bucket: "efd/autogen")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r["_measurement"] == "lsst.sal.MTDomeTrajectory.logevent_followingMode")
  |> filter(fn: (r) => r["_field"] == "enabled")
  |> last()
  |> pivot(rowKey: ["_measurement"], columnKey: ["_field"], valueColumn: "_value")
  |> map(fn: (r) => ({
    r with
    "1": 
      if r.enabled == true then "Dome following ENABLED"
      else "Dome following DISABLED"
})
)
|> keep(columns: [
    "1"
  ])

